/**
 * Typed client for the Hestia API.
 * Types come from `api-types.ts`, generated by `pnpm gen:types` from FastAPI's OpenAPI schema.
 */
import type { components } from "./api-types";

export type Schemas = components["schemas"];
export type Experiment = Schemas["ExperimentDetail"];
export type ExperimentSummary = Schemas["ExperimentSummary"];
export type Gravity = Schemas["Gravity"];
export type Outcome = Schemas["Outcome"];

export const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";

export class ApiError extends Error {
  constructor(
    public status: number,
    message: string,
  ) {
    super(message);
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(`${API_URL}${path}`, {
      cache: "no-store",
      ...init,
      headers: { "Content-Type": "application/json", ...init?.headers },
    });
  } catch {
    throw new ApiError(0, `Cannot reach the API at ${API_URL}. Is it running (make api)?`);
  }
  if (!res.ok) throw new ApiError(res.status, `${res.status} ${await res.text()}`);
  return (await res.json()) as T;
}

/** Await a promise without throwing, so pages can render an error state outside try/catch. */
export async function attempt<T>(
  promise: Promise<T>,
): Promise<{ data: T; error?: undefined } | { data?: undefined; error: unknown }> {
  try {
    return { data: await promise };
  } catch (error) {
    return { error };
  }
}

/** Diluent fractions default to 0 on the server. */
export type PredictInput = Omit<Schemas["PredictRequest"], "co2_percent" | "he_percent"> &
  Partial<Pick<Schemas["PredictRequest"], "co2_percent" | "he_percent">>;

export interface ExperimentFilters {
  fuel?: string;
  gravity?: Gravity;
  outcome?: Outcome;
  o2_min?: number;
  o2_max?: number;
}

function query(params: object): string {
  const entries = Object.entries(params).filter(([, v]) => v !== undefined && v !== "");
  return entries.length ? `?${new URLSearchParams(entries.map(([k, v]) => [k, String(v)]))}` : "";
}

export const api = {
  health: () => request<Schemas["HealthResponse"]>("/health"),

  listExperiments: (filters: ExperimentFilters = {}) =>
    request<Schemas["ExperimentList"]>(`/experiments${query(filters)}`),

  getExperiment: (code: string) =>
    request<Experiment>(`/experiments/${encodeURIComponent(code)}`),

  compare: (codes: string[]) =>
    request<Schemas["CompareResponse"]>(`/compare${query({ codes: codes.join(",") })}`),

  ranking: (target: "moon" | "mars") =>
    request<Schemas["RankingResponse"]>(`/ranking${query({ target })}`),

  stats: () => request<Schemas["StatsResponse"]>("/stats"),

  compareInsights: (codes: string[]) =>
    request<Schemas["CompareInsights"]>(`/compare/insights${query({ codes: codes.join(",") })}`),

  ask: (question: string, history: Schemas["ChatMessage"][] = []) =>
    request<Schemas["AskResponse"]>("/ask", {
      method: "POST",
      body: JSON.stringify({ question, history } satisfies Schemas["AskRequest"]),
    }),

  search: (q: string, signal?: AbortSignal) =>
    request<Schemas["SearchResponse"]>(`/search${query({ q })}`, { signal }),

  modelInfo: () => request<Schemas["ModelInfo"]>("/predict/model"),

  predict: (body: PredictInput) =>
    request<Schemas["PredictResponse"]>("/predict", {
      method: "POST",
      body: JSON.stringify(body),
    }),
};
